ntent": "", "publishTime": null, "translatedContent": null, "authorProfileImage": "https://lh3.googleusercontent.com/a-/ALV-UjXvmfdbY2WMO29Cq2pEGevUc3nHXinHDhCDUo_mrmfN724dY5UB=s120-c-rp-mo-br100"}]	[]	[{"day": "FRIDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "THURSDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "WEDNESDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "MONDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "SUNDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "SATURDAY", "openTime": [10, 0], "closeTime": [22, 0]}, {"day": "TUESDAY", "openTime": [10, 0], "closeTime": [22, 0]}]	0101000020E6100000DAE9622E04B45F40E078E34977C74240
