ge": "https://lh3.googleusercontent.com/a-/ALV-UjWYwk5yQUEFjfJytoiLKW_RNJRZpkb53Mg4ygotI-_LVBam95Rs=s120-c-rp-mo-br100"}]	[{"photoUri": "https://moisam-server.s3.ap-northeast-2.amazonaws.com/places/ChIJ-XR6lPujfDURSD_0UMsjSgQ/photos/0.png"}, {"photoUri": "https://moisam-server.s3.ap-northeast-2.amazonaws.com/places/ChIJ-XR6lPujfDURSD_0UMsjSgQ/photos/1.png"}, {"photoUri": "https://moisam-server.s3.ap-northeast-2.amazonaws.com/places/ChIJ-XR6lPujfDURSD_0UMsjSgQ/photos/2.png"}, {"photoUri": "https://moisam-server.s3.ap-northeast-2.amazonaws.com/places/ChIJ-XR6lPujfDURSD_0UMsjSgQ/photos/3.png"}]	[{"day": "FRIDAY", "openTime": [8, 0], "closeTime": [18, 0]}, {"day": "THURSDAY", "openTime": [8, 0], "closeTime": [18, 0]}, {"day": "WEDNESDAY", "openTime": [8, 0], "closeTime": [18, 0]}, {"day": "MONDAY", "openTime": [8, 0], "closeTime": [18, 0]}, {"day": "SUNDAY", "openTime": [10, 0], "closeTime": [17, 0]}, {"day": "SATURDAY", "openTime": [10, 0], "closeTime": [17, 0]}, {"day": "TUESDAY", "openTime": [8, 0], "closeTime": [18, 0]}]	0101000020E610000054617D4D20C25F401CCF6740BDC04240
